from pathlib import Path
s=Path('outputs/StarportSquad/scripts')
p=s/'operative.gd';t=p.read_text().replace(' root.set_meta("coat",coat)',' var knife = Gear.make_knife(root)\n knife.position = Vector3(.46,1.05,-.4)\n knife.visible = false\n root.set_meta("knife",knife)\n root.set_meta("coat",coat)');p.write_text(t)
p=s/'drone.gd';t=p.read_text().replace('var is_boss := false','var friendly := false\nvar slot := 0\nvar target_unit: Node3D\nvar knife: Node3D\nvar is_boss := false').replace(' collision_layer = 4',' collision_layer = 8 if friendly else 4').replace(' collision_mask = 1 | 2 | 4',' collision_mask = 1').replace(' var accent = F.mat(Color("ff7962"),1.5)',' var accent = F.mat(Color("51ffe0") if friendly else Color("ff7962"),1.5)').replace(' badge = F.text3d(model,',' knife = Gear.make_knife(model)\n knife.position = Vector3(.4,1.05,-.4)\n knife.visible = false\n badge = F.text3d(model,').replace('("首领 / 彩虹全套" if is_boss else Gear.SHORT[armor_tier])','("友军 %02d" % (slot+1) if friendly else ("首领 / 彩虹全套" if is_boss else Gear.SHORT[armor_tier]))')
t=t.replace(' var target = game.player.position',' target_unit = select_target()\n var target = target_unit.position if target_unit!=null else game.player.position\n var following = friendly and (target_unit==null or position.distance_to(game.player.position)>14)\n if following:\n  target_unit = null\n  target = game.player.position+formation_offset()').replace(' var visible_target = game.clear_line(global_position+Vector3.UP*1.4,(game.player.global_position+Vector3.UP*1.3),game.player)',' var visible_target = target_unit!=null and game.clear_line(global_position+Vector3.UP*1.4,target_unit.global_position+Vector3.UP*1.3,target_unit)').replace(' var destination = target if distance < 28 else home+',' var destination = target if friendly or distance < 28 else home+').replace(' if distance > 8 or not visible_target:',' if distance > (1.0 if following else 7.0) or (not visible_target and not following):').replace(' velocity.x = motion.x*(2.2+game.difficulty*.45)',' var speed = 7.8 if friendly else 2.2+game.difficulty*.45\n velocity.x = motion.x*speed').replace(' velocity.z = motion.z*(2.2+game.difficulty*.45)',' velocity.z = motion.z*speed').replace(' if windup >= 0:',' var melee = target_unit!=null and distance<2.4 and visible_target\n knife.visible = melee\n gun.visible = not melee\n knife.rotation.z = sin(fire_timer*18)*.6\n if melee:\n  windup = -1\n  eye.scale.y = 1\n  if fire_timer<=0:\n   fire_timer = .6\n   if target_unit==game.player:\n    game.player.damage(35*(2.0 if game.difficulty==3 else 1.0))\n   else:\n    target_unit.take_hit(80)\n  return\n if target_unit==null:\n  return\n if windup >= 0:').replace('(game.player.global_position+Vector3.UP*1.3)+','(target_unit.global_position+Vector3.UP*1.3)+').replace(' if game.difficulty>0 and distance>4',' if not friendly and game.difficulty>0 and distance>4').replace('game.throw_grenade(global_position+Vector3.UP*1.3,game.player.position)','game.throw_grenade(global_position+Vector3.UP*1.3,target_unit.position)').replace(' if game.difficulty == 0:\n  fire_timer = game.rng.randf_range(1.6,2.6)',' if friendly:\n  fire_timer = Gear.interval(weapon_kind,weapon_tier)*2.0\n  game.command.ally_shot(self,origin,planned_aim)\n  if ammo<=0:\n   reload_left = 1.55\n   fire_timer = reload_left\n elif game.difficulty == 0:\n  fire_timer = game.rng.randf_range(1.2,1.9)').replace('  game.kills += 1','  if not friendly:\n   game.kills += 1').replace('  game.player.shield = minf','  if friendly:\n   return\n  game.player.shield = minf')
t+='''
func formation_offset() -> Vector3:
 return game.player.global_basis*Vector3((slot%5-2)*1.8,0,2.5+float(slot/5)*2.0)

func select_target() -> Node3D:
 var closest: Node3D = null if friendly else game.player
 var limit = 22.0 if friendly else position.distance_to(game.player.position)
 var candidates = game.enemies if friendly else game.allies
 for unit in candidates:
  if is_instance_valid(unit) and unit.hp>0:
   var distance = position.distance_to(unit.position)
   if distance<limit and game.clear_line(position+Vector3.UP*1.3,unit.position+Vector3.UP*1.3,unit):
    closest = unit
    limit = distance
 return closest
''';p.write_text(t)
p=s/'game.gd';t=p.read_text().replace('PhysicsRayQueryParameters3D.create(old,next,3)','PhysicsRayQueryParameters3D.create(old,next,11)').replace('   if hit.collider == player:\n    player.damage(12)','   if hit.collider == player:\n    player.damage(12)\n   elif hit.collider.has_method("take_hit"):\n    hit.collider.take_hit(12)').replace('origin+direction*55,3','origin+direction*55,11').replace(' var pellets = 1 if bot.weapon_kind==0 else 9',' var pellets = 9 if bot.weapon_kind==1 else 1').replace('   if hit.collider==player:\n    total_damage +=','   if hit.collider!=player and hit.collider.has_method("take_hit"):\n    hit.collider.take_hit(20*(2 if difficulty==3 else 1))\n   if hit.collider==player:\n    total_damage +=');p.write_text(t)
